"use client";

import { createPortal } from "react-dom";
import { useCallback, useEffect, useRef, useState } from "react";
import styles from "./OptimizedDashboardVideo.module.scss";

const VIDEO_SRC = "/assets/videos/dashboard.webm";

/**
 * Inline muted loop preview when near viewport; click opens full popup with controls.
 */
export function OptimizedDashboardVideo() {
  const wrapRef = useRef<HTMLDivElement>(null);
  const inlineVideoRef = useRef<HTMLVideoElement>(null);
  const modalVideoRef = useRef<HTMLVideoElement>(null);
  const [inView, setInView] = useState(false);
  const [modalOpen, setModalOpen] = useState(false);
  const [modalError, setModalError] = useState(false);

  useEffect(() => {
    const el = wrapRef.current;
    if (!el) return;
    const obs = new IntersectionObserver(
      ([e]) => {
        if (e.isIntersecting) setInView(true);
      },
      { rootMargin: "120px", threshold: 0.08 }
    );
    obs.observe(el);
    return () => obs.disconnect();
  }, []);

  useEffect(() => {
    const v = inlineVideoRef.current;
    if (!v || !inView) return;
    if (modalOpen) {
      v.pause();
      return;
    }
    const tryPlay = () => {
      void v.play().catch(() => {});
    };
    v.addEventListener("loadeddata", tryPlay, { once: true });
    if (v.readyState >= HTMLMediaElement.HAVE_CURRENT_DATA) tryPlay();
    return () => v.removeEventListener("loadeddata", tryPlay);
  }, [inView, modalOpen]);

  const closeModal = useCallback(() => {
    const v = modalVideoRef.current;
    if (v) {
      v.pause();
      v.currentTime = 0;
    }
    setModalOpen(false);
    setModalError(false);
  }, []);

  const openModal = useCallback(() => {
    setModalOpen(true);
    setModalError(false);
  }, []);

  useEffect(() => {
    if (!modalOpen) return;
    const v = modalVideoRef.current;
    if (!v) return;
    const p = v.play();
    if (p && typeof p.catch === "function") {
      p.catch(() => setModalError(true));
    }
  }, [modalOpen]);

  useEffect(() => {
    if (!modalOpen) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") closeModal();
    };
    document.addEventListener("keydown", onKey);
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      document.removeEventListener("keydown", onKey);
      document.body.style.overflow = prev;
    };
  }, [modalOpen, closeModal]);

  const modal =
    modalOpen && typeof document !== "undefined"
      ? createPortal(
          <div
            className={styles.modalRoot}
            role="dialog"
            aria-modal="true"
            aria-label="Platform dashboard video"
          >
            <button
              type="button"
              className={styles.modalBackdrop}
              aria-label="Close video"
              onClick={closeModal}
            />
            <div className={styles.modalPanel}>
              <button
                type="button"
                className={styles.modalClose}
                onClick={closeModal}
                aria-label="Close"
              >
                ×
              </button>
              <video
                ref={modalVideoRef}
                className={styles.modalVideo}
                src={VIDEO_SRC}
                controls
                playsInline
                preload="auto"
                aria-label="Platform dashboard preview"
                onError={() => setModalError(true)}
              />
              {modalError && (
                <p className={styles.modalError} role="status">
                  Video could not be played.
                </p>
              )}
            </div>
          </div>,
          document.body
        )
      : null;

  return (
    <>
      <div ref={wrapRef} className={styles.wrap}>
        {inView ? (
          <video
            ref={inlineVideoRef}
            className={styles.video}
            src={VIDEO_SRC}
            preload="metadata"
            playsInline
            muted
            loop
            tabIndex={-1}
            aria-hidden
          />
        ) : (
          <div className={styles.skeleton} aria-hidden />
        )}
        {inView && (
          <button
            type="button"
            className={styles.playOverlay}
            onClick={openModal}
            aria-label="Open dashboard video in a popup"
          >
            <div className={styles.brand} aria-hidden>
              <div className={styles.brandText}>WHITEGUARD</div>
              <WhiteGuardMark />
            </div>
            <span className={styles.playIcon} aria-hidden />
          </button>
        )}
      </div>
      {modal}
    </>
  );
}

